CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE tool_status AS ENUM ('available','reserved','rented','service','written_off');
CREATE TYPE booking_status AS ENUM ('active','converted','cancelled');
CREATE TYPE rental_status AS ENUM ('active','completed','cancelled');
CREATE TYPE return_condition AS ENUM ('available','service');
CREATE TABLE tools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, category text, brand text, model text, internal_number text NOT NULL UNIQUE, photo_url text, purchase_date date, purchase_cost integer NOT NULL CHECK (purchase_cost >= 0), daily_rate integer NOT NULL CHECK (daily_rate >= 0), default_deposit integer NOT NULL CHECK (default_deposit >= 0), description text, status tool_status NOT NULL DEFAULT 'available', service_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tool_components (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tool_id uuid NOT NULL REFERENCES tools(id) ON DELETE CASCADE, name text NOT NULL, sort_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL, phone text NOT NULL, document_details text, address text, comment text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES clients(id), start_date date NOT NULL, planned_return_date date NOT NULL CHECK(planned_return_date >= start_date), status booking_status NOT NULL DEFAULT 'active', comment text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE booking_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, tool_id uuid NOT NULL REFERENCES tools(id), daily_rate_snapshot integer NOT NULL, deposit_snapshot integer NOT NULL, UNIQUE(booking_id, tool_id));
CREATE TABLE rentals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES clients(id), booking_id uuid UNIQUE REFERENCES bookings(id), issue_date date NOT NULL, planned_return_date date NOT NULL CHECK(planned_return_date >= issue_date), completed_date date, status rental_status NOT NULL DEFAULT 'active', calculated_amount integer NOT NULL, final_rental_amount integer NOT NULL, deposit_amount integer NOT NULL DEFAULT 0, deposit_received boolean NOT NULL DEFAULT false, payment_received_amount integer NOT NULL DEFAULT 0, is_paid boolean NOT NULL DEFAULT false, comment text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rental_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rental_id uuid NOT NULL REFERENCES rentals(id) ON DELETE CASCADE, tool_id uuid NOT NULL REFERENCES tools(id), daily_rate_snapshot integer NOT NULL, calculated_amount integer NOT NULL, income_amount integer NOT NULL, deposit_snapshot integer NOT NULL, issued_components jsonb NOT NULL DEFAULT '[]', returned_components jsonb NOT NULL DEFAULT '[]', return_condition return_condition, return_comment text, UNIQUE(rental_id, tool_id));
CREATE TABLE maintenance_expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tool_id uuid NOT NULL REFERENCES tools(id), expense_date date NOT NULL, amount integer NOT NULL CHECK(amount >= 0), comment text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys (key text PRIMARY KEY, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX booking_items_tool_idx ON booking_items(tool_id); CREATE INDEX rental_items_tool_idx ON rental_items(tool_id);
